"""#011 visual builder: budget burn-off at the office."""
import json, pathlib, re
D=pathlib.Path(__file__).resolve().parent
A=D.parent.parent/"assets"/"character"
def inner(name):
    s=(A/name).read_text(encoding="utf-8")
    return re.sub(r"^<svg[^>]*>|</svg>$","",s.strip(),flags=re.S)
S={k:inner(v) for k,v in {
 "front":"man/front.svg","side":"man/side.svg","back":"man/back.svg",
 "blank":"man/face_blank.svg","distant":"man/face_distant.svg",
 "glance":"man/face_glance.svg","resolve":"man/face_resolve.svg",
 "woman":"woman_pass.svg"}.items()}
TL=json.loads((D/"timeline.json").read_text(encoding="utf-8"))
HTML=r"""<!doctype html><html><head><meta charset="utf-8"><style>
html,body{margin:0;background:#050506}#stage{position:relative;width:1080px;height:1920px;overflow:hidden;background:#0c0c0f;font-family:"Noto Serif CJK JP",serif}
#art{position:absolute;inset:0;width:1080px;height:1920px}
#subbg{position:absolute;left:0;right:0;bottom:90px;height:580px;background:linear-gradient(transparent,rgba(0,0,0,.8) 25%,rgba(0,0,0,.8) 78%,transparent);opacity:0}
#sub{position:absolute;left:45px;right:45px;bottom:175px;text-align:center;white-space:pre-line;color:#f0eee9;font-size:50px;line-height:1.48;letter-spacing:.04em;text-shadow:0 2px 12px #000}
#fade{position:absolute;inset:0;background:#000;opacity:0}
.neon{font-weight:800;letter-spacing:.08em;color:#ffe5f0;-webkit-text-stroke:3px #ff2e88;text-shadow:0 0 7px #ff7ab4,0 0 22px #ff2e88,0 0 55px #ff2e88}
</style></head><body><div id="stage"><svg id="art" viewBox="0 0 1080 1920"></svg><div id="subbg"></div><div id="sub"></div><div id="fade"></div></div>
<script>
const S=__SVGS__,TL=__TL__;
const JP='font-family="Noto Serif CJK JP,serif"';
function rect(x,y,w,h,c,r,extra){return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+(r||0)+'" fill="'+(c||"#252529")+'" '+(extra||'')+'/>'}
function txt(x,y,s,size,fill,extra){return '<text x="'+x+'" y="'+y+'" '+JP+' font-size="'+(size||30)+'" fill="'+(fill||"#e9e6df")+'" '+(extra||'')+'>'+s+'</text>'}
function man(k,vb,x,y,w,h){return '<svg x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" viewBox="'+vb+'" preserveAspectRatio="xMidYMid meet">'+S[k]+'</svg>'}
function cam(s,z,cx,cy,dx,dy){return '<g transform="translate('+(540+(dx||0))+' '+(950+(dy||0))+') scale('+(z||1)+') translate('+(-(cx||540))+' '+(-(cy||950))+')">'+s+'</g>'}
function base(s){return '<svg viewBox="0 0 1080 1920" width="1080" height="1920"><defs><linearGradient id="window" x2="0" y2="1"><stop stop-color="#d8d5ce" stop-opacity=".28"/><stop offset="1" stop-color="#d8d5ce" stop-opacity="0"/></linearGradient><linearGradient id="street" x2="0" y2="1"><stop stop-color="#45454b"/><stop offset="1" stop-color="#0b0b0d"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="24"/></filter></defs><rect width="1080" height="1920" fill="#0b0b0d"/>'+s+'</svg>'}
function phone(screen,x,y){x=x||260;y=y||280;return rect(x,y,560,1160,"#08080a",70,'stroke="#77777d" stroke-width="12"')+rect(x+22,y+35,516,1092,"#ddd9d0",40)+rect(x+220,y+14,120,12,"#77777d",6)+screen}

function glow(x,y,r){return '<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="#e9e6df" opacity=".12" filter="url(#blur)"/>'}
function fbox(x,y,w,h,r){let cx=w/2,cy=h*0.38,rr=h*0.2;return '<g transform="translate('+x+' '+y+') rotate('+(r||0)+' '+(w/2)+' '+(h/2)+')">'+rect(0,0,w,h,"#d8d5ce",6,'stroke="#77777d" stroke-width="3"')+rect(0,h*0.74,w,h*0.26,"#45454b",0)+[0,1,2,3,4].map(i=>'<ellipse cx="'+cx+'" cy="'+(cy-rr*.55)+'" rx="'+(rr*.28)+'" ry="'+(rr*.55)+'" fill="#45454b" transform="rotate('+(i*72+20)+' '+cx+' '+cy+')"/>').join('')+'<circle cx="'+cx+'" cy="'+cy+'" r="'+(rr*.14)+'" fill="#d8d5ce"/></g>'}
function pile(cx,y,bw,bh,rows,from){let g='',n=0;for(let r=0;r<rows;r++){let cnt=rows-r;for(let i=0;i<cnt;i++){let x=cx-cnt*bw/2+i*bw+((r*7+i*5)%3-1)*3,yy=y-(r+1)*bh;if(n++<(from===undefined?99:from))g+=fbox(x,yy,bw-6,bh-4,((r*3+i*2)%5-2)*1.2)}}return g}
function tagcard(x,y,w,h,s,size,dark){return rect(x,y,w,h,dark?"#16161b":"#f4f2ec",10,'stroke="#9a978f" stroke-width="3"')+txt(x+w/2,y+h/2+size*0.35,s,size,dark?"#e9e6df":"#111",'text-anchor="middle" font-weight="800"')}
function shelves(){let g='';for(let i=0;i<2;i++){let x=i?830:0;g+=rect(x,320,250,860,"#16161b",0)+[0,1,2,3].map(j=>rect(x+(i?0:0),420+j*200,250,16,"#2a2a2e")+rect(x+20,340+j*200,60,80,"#202025")+rect(x+110,360+j*200,80,60,"#1d1d22")).join('')}return g}
function lights(){let g='';for(let i=0;i<4;i++)g+=rect(120+i*230,150,160,16,"#e9e6df",6,'opacity=".28"')+rect(60+i*230,150,280,320,"#e9e6df",0,'opacity=".02"');return g}
function chair(x,y,s,fill,op){fill=fill||"#d8d5ce";return '<g transform="translate('+x+' '+y+') scale('+(s||1)+')" opacity="'+(op===undefined?1:op)+'">'+rect(14,0,100,92,fill,16,'stroke="#77777d" stroke-width="4"')+rect(0,104,128,28,fill,10,'stroke="#77777d" stroke-width="4"')+rect(58,132,12,52,"#45454b",3)+'<path d="M64 184 L10 206 M64 184 L118 206 M64 184 V210" stroke="#45454b" stroke-width="9" stroke-linecap="round"/>'+'<circle cx="10" cy="212" r="8" fill="#45454b"/><circle cx="118" cy="212" r="8" fill="#45454b"/><circle cx="64" cy="216" r="8" fill="#45454b"/></g>'}
function stackc(cx,y,n){let g='';for(let i=0;i<n;i++)g+=chair(cx-64+(i%2?14:-14)+(i*5%9),y-i*26,1,"#d8d5ce",1);return g}
function arrowR(x,y,w,c){c=c||"#e9e6df";return '<path d="M'+x+' '+y+' H'+(x+w)+'" stroke="'+c+'" stroke-width="10"/><path d="M'+(x+w-34)+' '+(y-32)+' L'+(x+w)+' '+y+' L'+(x+w-34)+' '+(y+32)+'" stroke="'+c+'" stroke-width="10" fill="none"/>'}
function arrowD(x,y,h,c){c=c||"#e9e6df";return '<path d="M'+x+' '+y+' V'+(y+h)+'" stroke="'+c+'" stroke-width="10"/><path d="M'+(x-32)+' '+(y+h-34)+' L'+x+' '+(y+h)+' L'+(x+32)+' '+(y+h-34)+'" stroke="'+c+'" stroke-width="10" fill="none"/>'}
function teaser(t,k){return base(rect(0,0,1080,1920,"#0a0a0d")+'<g opacity=".9">'+cam(man("blank","0 0 300 320",-60,60,1200,1280),1,540,850)+'</g>'+glow(540,1330,380)+'<g opacity=".7">'+stackc(300,1180,5)+stackc(780,1180,5)+'</g>'+'<g transform="translate(700 1040) rotate(-6)">'+tagcard(0,0,240,110,"×42",70)+'</g>')}
function room(t,k){let g='';for(let i=0;i<3;i++)g+=chair(150+i*270,830,.9,"#2a2a2e",1)+chair(150+i*270,1010,.9,"#2a2a2e",1);return base(rect(0,0,1080,1920,"#0b0b0e")+lights()+rect(60,330,960,360,"#16161b",8,'stroke="#45454b" stroke-width="5"')+txt(390,540,"下期予算",110,"#e9e6df",'text-anchor="middle" font-weight="800" letter-spacing="14"')+rect(0,1180,1080,740,"#101014")+g+rect(80,960,920,120,"#202025",14,'stroke="#77777d" stroke-width="5"')+man("back","0 0 400 1000",730,330,300,780)+txt(540,250,"水曜　17:40",44,"#8a8a90",'text-anchor="middle" letter-spacing="10"'))}
function budget(t,k){let n=Math.min(1,k*1.8),w=Math.round(760*(1-n*0.0)),used=0.64;return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,760,420)+txt(540,330,"下期の予算",54,"#8a8a90",'text-anchor="middle" letter-spacing="10"')+txt(540,640,"残り",64,"#e9e6df",'text-anchor="middle" font-weight="700"')+txt(540,830,"¥1,117,000",150,"#e9e6df",'text-anchor="middle" font-weight="800" opacity="'+(0.2+0.8*n)+'"')+rect(160,930,760,70,"#16161b",12,'stroke="#77777d" stroke-width="4"')+rect(160,930,760*used,70,"#45454b",12)+rect(160+760*used,930,760*(1-used),70,"#e9e6df",12,'opacity="'+(0.3+0.7*n)+'"')+txt(540,1100,"12月まで",64,"#e9e6df",'text-anchor="middle" font-weight="700"'))}
function chairs(t,k){let n=Math.min(1,k*2);return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,700,380)+txt(270,300,"去年買った",50,"#8a8a90",'text-anchor="middle"')+chair(160,380,1.7,"#a8a59d",1)+txt(270,900,"壊れていない",52,"#e9e6df",'text-anchor="middle" font-weight="700"')+arrowR(470,600,130)+txt(810,300,"新しい椅子",50,"#e9e6df",'text-anchor="middle"')+chair(700,380,1.7,"#d8d5ce",n)+'<g opacity="'+n+'">'+tagcard(610,900,400,150,"¥26,600",76)+tagcard(710,1080,200,100,"×42",64,true)+'</g>')}
function giveback(t,k){let n=Math.min(1,k*2.2);return base(rect(0,0,1080,1920,"#0b0b0e")+txt(540,300,"使い切らない",70,"#e9e6df",'text-anchor="middle" font-weight="700"')+rect(120,400,360,250,"#1b1b20",14,'stroke="#9a978f" stroke-width="4"')+txt(300,500,"予算",60,"#8a8a90",'text-anchor="middle"')+txt(300,590,"残り",68,"#e9e6df",'text-anchor="middle" font-weight="800"')+arrowR(500,525,100)+rect(620,400,340,250,"#1b1b20",14,'stroke="#9a978f" stroke-width="4"')+txt(790,555,"会社",76,"#e9e6df",'text-anchor="middle"')+'<g opacity="'+n+'">'+rect(240,800,600,150,"#e9e6df",14)+txt(540,900,"会社に返す",76,"#111",'text-anchor="middle" font-weight="800"')+'</g>')}
function shrink(t,k){let n=Math.min(1,Math.max(0,(k-.25)*2)),h2=620-n*220;return base(rect(0,0,1080,1920,"#0b0b0e")+txt(540,300,"来年のうちの部の予算",56,"#e9e6df",'text-anchor="middle" font-weight="700"')+rect(0,1000,1080,8,"#45454b")+rect(220,1000-620,240,620,"#45454b",8)+txt(340,1080,"今年",50,"#8a8a90",'text-anchor="middle"')+rect(620,1000-h2,240,h2,"#e9e6df",8)+txt(740,1080,"来年",50,"#e9e6df",'text-anchor="middle"')+(n>.3?'<path d="M600 '+(380)+' H880" stroke="#8a8a90" stroke-width="5" stroke-dasharray="12 10"/>'+txt(740,330+0,"",1):'')+'<g opacity="'+n+'">'+rect(300,1150,480,110,"#16161b",14,'stroke="#9a978f" stroke-width="4"')+txt(540,1225,"返した分だけ減る",52,"#e9e6df",'text-anchor="middle" font-weight="700"')+'</g>')}
function order(t,k){let n=Math.min(1,k*2);return base(rect(0,0,1080,1920,"#0b0b0e")+txt(540,300,"先に",60,"#8a8a90",'text-anchor="middle" letter-spacing="10"')+rect(160,350,760,200,"#e9e6df",16)+txt(540,480,"使う金額",96,"#111",'text-anchor="middle" font-weight="800"')+arrowD(540,590,150)+txt(540,820,"あとから",60,"#8a8a90",'text-anchor="middle" letter-spacing="10"')+rect(160,870,760,200,"#16161b",16,'stroke="#9a978f" stroke-width="5" stroke-dasharray="14 10"')+txt(540,1000,"買う物",96,"#e9e6df",'text-anchor="middle" font-weight="800" opacity="'+(0.3+0.7*n)+'"')+txt(540,1160,"（まだ決まっていない）",44,"#8a8a90",'text-anchor="middle"'))}
function memo(t,k){let n=Math.min(3,Math.floor(k*4)),L=["椅子","シュレッダー","モニター"],g='';for(let i=0;i<3;i++){let y=520+i*170;g+=txt(180,y,(i<n?"☑ ":"☐ ")+L[i],84,"#111",'font-weight="700"')+'<path d="M150 '+(y+34)+' H930" stroke="#bdb9ae" stroke-width="3"/>'}return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,760,420)+'<g transform="rotate(-2 540 760)">'+rect(100,300,880,900,"#e4e1d8",14)+rect(100,300,880,90,"#9a978f",14)+txt(180,365,"メモ　候補",52,"#111",'font-weight="800"')+g+'</g>')}
function ringi(t,k){let n=Math.min(1,k*1.6);return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,760,420)+'<g transform="translate(120 280)">'+rect(0,0,840,980,"#e9e6df",12)+txt(60,110,"稟議書",78,"#111",'font-weight="800" letter-spacing="14"')+rect(60,170,720,6,"#111")+txt(60,270,"購入品　椅子　42脚",50,"#111")+txt(60,370,"金額　¥1,117,200",50,"#111")+rect(60,430,720,6,"#9a978f")+txt(60,520,"購入理由",56,"#111",'font-weight="800"')+'<g opacity="'+n+'">'+txt(60,620,"座面の劣化により、",56,"#111")+txt(60,700,"業務効率に影響が",56,"#111")+txt(60,780,"出ているため",56,"#111")+'</g>'+'</g>')}
function disposal(t,k){let n=Math.min(1,k*1.6);return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,700,380)+txt(280,300,"古い椅子",58,"#e9e6df",'text-anchor="middle" font-weight="700"')+chair(150,380,1.5,"#a8a59d",1)+arrowR(420,640,170)+rect(620,430,340,420,"#1b1b20",14,'stroke="#9a978f" stroke-width="4"')+txt(790,670,"業者",84,"#e9e6df",'text-anchor="middle" font-weight="800"')+'<g opacity="'+n+'">'+rect(180,980,720,150,"#e9e6df",14)+txt(540,1080,"お金を払う",78,"#111",'text-anchor="middle" font-weight="800"')+'</g>')}
function stamp(t,k){let hit=k>.55,d=Math.min(1,Math.max(0,(k-.55)*5));return base(rect(0,0,1080,1920,"#0b0b0e")+glow(540,760,420)+'<g transform="translate(140 300)">'+rect(0,0,800,900,"#e9e6df",12)+txt(50,100,"稟議書",64,"#111",'font-weight="800" letter-spacing="12"')+txt(50,220,"購入理由",44,"#111",'font-weight="800"')+rect(50,260,700,70,"#bdb9ae",6)+rect(50,360,520,24,"#bdb9ae",6)+rect(50,420,600,24,"#bdb9ae",6)+rect(480,620,220,220,"none",0)+(hit?'<circle cx="590" cy="720" r="'+(100*(0.7+0.3*d))+'" fill="none" stroke="#111" stroke-width="14" opacity="'+d+'"/><text x="590" y="750" '+JP+' font-size="84" font-weight="800" fill="#111" text-anchor="middle" opacity="'+d+'">承</text>':'')+'</g>'+(hit?'':'<g transform="translate('+(430)+' '+(260+k*500)+')">'+rect(0,0,120,300,"#45454b",16)+rect(-30,300,180,90,"#77777d",12)+'</g>'))}
function ink(t,k){let z=1.1+k*.1;return base(rect(0,0,1080,1920,"#0a0a0c")+cam(glow(540,760,420)+rect(80,220,920,980,"#e9e6df",14)+'<circle cx="540" cy="700" r="230" fill="none" stroke="#111" stroke-width="30"/><circle cx="540" cy="700" r="196" fill="none" stroke="#111" stroke-width="5" opacity=".5"/><text x="540" y="780" '+JP+' font-size="240" font-weight="800" fill="#111" text-anchor="middle">承</text><ellipse cx="420" cy="540" rx="60" ry="26" fill="#fff" opacity="'+(0.35+0.2*Math.sin(k*5))+'" transform="rotate(-30 420 540)"/>',z,540,700))}
function hand(t,k){let m=Math.min(1,k*1.6),lx=-120+m*120,rx=120-m*120;return base(rect(0,0,1080,1920,"#0a0a0c")+glow(540,760,300)+rect(180,300,720,940,"#e9e6df",12)+txt(540,420,"稟議書",84,"#111",'text-anchor="middle" font-weight="800" letter-spacing="14"')+rect(260,480,560,20,"#bdb9ae",6)+rect(260,540,460,20,"#bdb9ae",6)+'<g transform="translate('+lx+' 0)">'+'<rect x="-80" y="1100" width="460" height="86" rx="43" fill="#8a8a90" transform="rotate(-8 300 1140)"/>'+'</g><g transform="translate('+rx+' 0)">'+'<rect x="720" y="1090" width="460" height="86" rx="43" fill="#b3afa5" transform="rotate(8 780 1130)"/></g>'+'<circle cx="540" cy="1140" r="'+(40+m*80)+'" fill="#e9e6df" opacity="'+(0.05+0.12*m)+'" filter="url(#blur)"/>')}
function warm(t,k){let c='';for(let i=0;i<3;i++){let ph=(k*1.2+i*.33)%1;c+='<path d="M'+(420+i*120)+' '+(960-ph*300)+' c-36 -50 36 -90 0 -140 c-36 -50 36 -90 0 -140" fill="none" stroke="#e9e6df" stroke-width="7" stroke-linecap="round" opacity="'+(0.5*(1-ph))+'"/>'}return base(rect(0,0,1080,1920,"#0a0a0c")+glow(540,1000,380)+rect(0,0,0,0,"#000")+'<rect x="-30" y="1010" width="620" height="110" rx="55" fill="#8a8a90" transform="rotate(-6 300 1060)"/><rect x="500" y="1000" width="620" height="110" rx="55" fill="#b3afa5" transform="rotate(6 800 1050)"/>'+c+txt(540,300,"一秒",64,"#8a8a90",'text-anchor="middle" letter-spacing="12"'))}
function street(){let w='';for(let r=0;r<5;r++)for(let c=0;c<6;c++)w+=rect(90+c*150,160+r*130,100,80,"#e9e6df",4,'opacity="'+(((r*7+c*3)%4===0)?.34:.08)+'"');return base('<rect width="1080" height="1920" fill="url(#street)"/>'+rect(40,120,1000,740,"#16161b",6)+w+rect(430,720,220,140,"#202025",4)+glow(540,790,260)+'<path d="M0 1300 L1080 1300 V1920 H0Z" fill="#121216"/>'+[0,1,2,3].map(i=>rect(70+i*270,1360,140,10,"#45454b",3)).join('')+cam(man("back","0 0 400 1000",270,560,520,1050),1,540,1050))}
function punchline(){return base(rect(0,0,1080,1920,"#0c0c0f")+glow(560,1250,260)+cam(man("distant","0 0 300 320",-100,180,1280,1370),1.07,540,850))}
function woman(t,k){let x=-620+(1560+620)*Math.max(0,Math.min(1,k));return base('<rect width="1080" height="1920" fill="#0a0a0c"/><rect x="0" y="1120" width="1080" height="800" fill="#202025"/><g transform="translate('+(x-360)+' 740) scale(1.3)">'+S.woman+'</g>')}
function eyes(t,k,start){let key=t<start+.15?"blank":t<start+.85?"glance":"resolve";return base('<svg x="120" y="800" width="840" height="330" viewBox="80 145 140 55" preserveAspectRatio="xMidYMid meet">'+S[key]+'</svg>')}
function flyer(){return base('<rect width="1080" height="1920" fill="#09090b"/><rect x="220" y="-120" width="640" height="2200" fill="#202025"/><g transform="translate(290 210) rotate(-3)"><image href="../../assets/flyers/flyer_a.png" width="440" height="620"/></g><g transform="translate(420 850) rotate(3)"><image href="../../assets/flyers/flyer_c.png" width="430" height="620"/></g><rect width="1080" height="1920" fill="#000" opacity=".22"/>')}
const SCN={teaser:teaser,room:room,budget:budget,chairs:chairs,giveback:giveback,shrink:shrink,order:order,memo:memo,ringi:ringi,disposal:disposal,punchline:punchline,stamp:stamp,ink:ink,hand:hand,warm:warm,street:street,woman:woman,eyes:eyes,flyer:flyer,neon:function(){return base("")},black:function(){return base("")},cut:function(){return base("")}};
function render(t){
let sh=TL.shots.find(s=>t>=s[0]&&t<s[1])||TL.shots[TL.shots.length-1],k=(t-sh[0])/Math.max(.001,sh[1]-sh[0]);
let art=document.getElementById("art");art.innerHTML=SCN[sh[2]](t,k,sh[0]);
if(sh[2]==="black"||sh[2]==="neon"){
let final=sh[2]==="neon",d=t-sh[0],f=[1,0,1,1,0,0,1,0,1,1,1,1],on=d<.65?f[Math.floor(d/.05)%f.length]:1;
let tag=final?"くだらない世界　#011":"#011　予算消化の椅子";
art.innerHTML+='<foreignObject x="0" y="'+(final?330:500)+'" width="1080" height="1400"><div xmlns="http://www.w3.org/1999/xhtml" style="text-align:center;opacity:'+on+'"><div class="neon" style="font-size:'+(final?145:104)+'px;writing-mode:vertical-rl;text-align:start;display:inline-block;height:'+(final?1010:760)+'px">そうだ、<br>風俗行こう。</div><div style="color:#ddd;font-size:34px;letter-spacing:12px;margin-top:28px">'+tag+'</div></div></foreignObject>';
}
let sub=TL.subs.find(s=>t>=s[0]&&t<s[1]);
document.getElementById("sub").textContent=sub?sub[2]:"";
document.getElementById("subbg").style.opacity=sub?"1":"0";
document.getElementById("sub").style.fontSize=t<TL.teaser_end?"62px":"50px";
document.getElementById("fade").style.opacity=t>TL.total-.55?(t-(TL.total-.55))/.55:0;
}
window.render=render;
</script></body></html>"""
html=HTML.replace("__SVGS__",json.dumps(S,ensure_ascii=False)).replace("__TL__",json.dumps(TL,ensure_ascii=False))
(D/"ep.html").write_text(html,encoding="utf-8")
print("scene html written",len(html))
